// SvelteKit advanced data loading
// src/routes/products/[slug]/+page.server.ts
import { error } from '@sveltejs/kit';
import type { PageServerLoad, EntryGenerator } from './$types';

export const load: PageServerLoad = async ({ params, locals, setHeaders, depends }) => {
  depends('app:product');

  const product = await db.product.findUnique({
    where: { slug: params.slug },
    include: {
      reviews: { take: 10, orderBy: { createdAt: 'desc' } },
      relatedProducts: { take: 4 }
    }
  });

  if (!product) throw error(404, 'Product not found');

  // Set HTTP caching headers
  setHeaders({
    'Cache-Control': 'public, max-age=60, s-maxage=300'
  });

  // Stream reviews (slow query)
  const reviewsPromise = loadMoreReviews(product.id);

  return {
    product,
    streamed: {
      reviews: reviewsPromise
    }
  };
};

// Static generation for products (SSG)
export const entries: EntryGenerator = async () => {
  const products = await db.product.findMany({
    select: { slug: true }
  });
  return products.map(p => ({ slug: p.slug }));
};

